 const w=Number(d?.w||324.4),h=Number(d?.h||120),srcW=640,srcH=244,scale=Math.min(w/srcW,h/srcH),imgW=srcW*scale,imgH=srcH*scale,imgX=(w-imgW)/2,imgY=(h-imgH)/2;
