 return '<g class="hcfa-modbus-master" font-family="Arial,sans-serif"><rect x="4" y="4" width="232" height="142" rx="8" fill="#eef2f5" stroke="#475569"/><rect x="24" y="24" width="192" height="76" rx="4" fill="#1f2937"/><text x="120" y="48" text-anchor="middle" font-size="13" fill="#70f08c">HCFA · MODBUS RTU</text><text x="120" y="68" text-anchor="middle" font-family="monospace" font-size="13" fill="#fff">EIA485 · MASTER</text><text x="120" y="88" text-anchor="middle" font-family="monospace" font-size="9" fill="'+statusColor+'">'+status+'</text><circle cx="199" cy="38" r="5" fill="'+statusColor+'" stroke="#0f172a"/><text x="38" y="122" font-size="11" fill="#166534">485+</text><text x="166" y="122" font-size="11" fill="#7c3aed">485−</text><line x1="75" y1="118" x2="105" y2="118" stroke="#166534" stroke-width="3"/><line x1="135" y1="118" x2="165" y2="118" stroke="#7c3aed" stroke-width="3"/></g>';
