function markup(c,d){if(d?.id===H.id)return driveMarkup(c,true);if(d?.id===H.motorId)return motorMarkup(c,d);if(d?.hcfaPulseSource)return pulseMarkup(c);if(d?.hcfaModbusMaster)return modbusMarkup(c);return '';}
