function readouts(c){const s=c._hcfa||{};return [['P21.01','Motor hızı',s.rpm,'rpm'],['P21.03','Hız talimatı',s.commandRpm,'rpm'],['P21.04','Anlık tork',s.torquePercent,'%'],['P21.05','Motor akımı',s.current,'A'],['P21.06','DC bara',s.bus,'V'],['P21.07','Encoder sayımı',s.encoderCounts,'count'],['POS','Komut pozisyonu',s.positionUnits,'unit'],['IN','Pulse frekansı',s.pulseHz,'Hz']];}
