function live(c){const s=c._hcfa||{};return '<div class="v20-live-heading">'+status(c)+'</div><div class="v20-big-frequency">'+esc(display(c))+'</div><div class="v20-readouts">'+readouts(c).map(([k,n,v,u])=>'<div><small>'+k+' · '+n+'</small><b>'+fmt(v,Math.abs(Number(v)||0)>999?0:2)+' <span>'+u+'</span></b></div>').join('')+'</div><div class="v20-io">'+Array.from({length:8},(_,i)=>'<span class="'+(s.di?.[i]?'on':'')+'">DI'+(i+1)+'</span>').join('')+'</div>';}
