 if(tab==='monitor')main.innerHTML='<div data-hcfa-live></div><div class="v20-command-bar">'+[['servo','S-ON panel testi'],['reset','RESET'],['home','HOME'],['pulse','Pulse test aç/kapat']].map(([a,n])=>'<button data-hcfa-command="'+a+'">'+n+'</button>').join('')+'</div><label>Pulse test frekansı (Hz)<input data-hcfa-env="virtualPulseHz" type="number" min="0" max="500000" value="'+h.virtualPulseHz+'"></label><label>Pulse yönü<select data-hcfa-env="virtualDirection"><option value="1"'+(h.virtualDirection>=0?' selected':'')+'>CW / +</option><option value="-1"'+(h.virtualDirection<0?' selected':'')+'>CCW / −</option></select></label><details><summary>Eğitim yükü ve sıcaklık</summary><label>Yük (%)<input data-hcfa-env="load" type="number" min="0" max="350" value="'+h.load+'"></label><label>Sürücü sıcaklığı (°C)<input data-hcfa-env="temperature" type="number" min="0" max="120" value="'+h.temperature+'"></label></details>';
