  modal.innerHTML='<section class="v20-dialog" role="dialog" aria-modal="true" aria-labelledby="hcfaTitle"><header><div><small>HCFA · X2E · 400 W</small><h2 id="hcfaTitle">SV-X2EA040A-A · Servo devreye alma</h2></div><button id="hcfaClose">×</button></header><nav role="tablist"><button role="tab" data-hcfa-tab="monitor">Çalışma ekranı</button><button role="tab" data-hcfa-tab="parameters">Parametreler</button><button role="tab" data-hcfa-tab="connections">Bağlantılar</button><button role="tab" data-hcfa-tab="modbus">Modbus RTU</button></nav><div id="hcfaError" role="alert" hidden></div><main id="hcfaContent"></main><footer>HCFA X2E User Manual V2.0 / HW INS V2.2 · ayarlar projeyle kaydedilir. <span id="hcfaOwner"></span></footer></section>';
  root.document.body.appendChild(modal);
  modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('#hcfaClose')){hide();return;}const t=e.target.closest('[data-hcfa-tab]'),cmd=e.target.closest('[data-hcfa-command]'),mb=e.target.closest('[data-hcfa-modbus]');if(t){tab=t.dataset.hcfaTab;content();return;}if(cmd){command(owner,cmd.dataset.hcfaCommand);return;}if(mb){if(!editor().snapshot())return;const a=modal.querySelector('#hcfaMbAddress').value,v=modal.querySelector('#hcfaMbValue').value,r=H.writeModbus(owner,a,v);error(r.error);if(r.ok){editor().render(true);editor().scheduleSave();content();}}});
