  modal.addEventListener('change',e=>{if(!owner)return;const key=e.target.dataset.hcfaParam,env=e.target.dataset.hcfaEnv;if(e.target.id==='hcfaGroup'){group=e.target.value;modal.querySelector('#hcfaRows').innerHTML=rows();return;}if(!key&&!env)return;if(!editor().snapshot())return;let r={ok:true};if(key)r=H.set(owner,key,e.target.value);else{const h=H.config(owner),n=Number(e.target.value);if(!Number.isFinite(n))r={ok:false,error:'Geçersiz değer'};else h[env]=n;}error(r.error);if(r.ok){editor().render(true);editor().scheduleSave();sync();}else if(key)e.target.value=H.config(owner).params[key];});
